    async loadWalletBalance() {
        // Live balance instead of the cached (stale) config; light skips transactions.
        if (Salla.config.isGuest())
            return;
        this.walletBalanceLoading = true;
        try {
            // withoutNotifier: a failed background fetch must not toast the shopper.
            const resp = await salla.api.withoutNotifier(() => salla.api.request('/balance/wallet?light=1'));
            const balance = Number(resp?.data?.balance) || 0;
            // Currency stays from config — it doesn't go stale like the amount.
            this.walletBalance = balance
                ? Salla.money({ amount: Number(balance.toFixed(2)), currency: Salla.config.get('user.currency_code') })
                : '';
            this.walletBalanceLoaded = true; // cache for the rest of this page load
        }
        catch {
            // keep the last value on failure (retries on next open)
        }
        finally {
            this.walletBalanceLoading = false;
        }
    }
